import React from "react";
import Navbar from "../../components/navbar"; // Reusable Navbar Component
import SidePanel from "../../components/sidePanel"; // Reusable SidePanel Component
import "./StudentDashboard.css";

const StudentDashboard = () => {
  return (
    <div className="student-dashboard">
      <Navbar />
      <div className="dashboard-body">
        <SidePanel />
        <main className="dashboard-main">
          <h1>Welcome, Student!</h1>
          <p>Here are your available options:</p>
          <div className="dashboard-features">
            <div className="feature-card">Proposal Submission</div>
            <div className="feature-card">Documentation</div>
            <div className="feature-card">Deadlines</div>
            <div className="feature-card">Feedback</div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default StudentDashboard;
